class Solution {
public:
    int houseCount(Street* street, int k) {
        while (!street->isDoorOpen()) street->moveRight();
        int answer=0;
        for (int distance=1;distance<=k;++distance) {
            street->moveRight();
            if(street->isDoorOpen()) {
                answer=distance;
                street->closeDoor();
            }
        }
        return answer;
    }
};
